Algoritmo Congelar
  Definir notas Como Vector<Entero> <- Vector();
  notas.Agregar(7);
  Definir foto Como Inmutable<Vector<Entero>> <- Instantanea(notas);
  notas.Agregar(9);
  Escribir foto.Longitud(), " ", notas.Longitud(), " ", foto[0];
FinAlgoritmo

Algoritmo EscribirFoto
  Definir notas Como Vector<Entero> <- Vector();
  Definir foto Como Inmutable<Vector<Entero>> <- Instantanea(notas);
  foto.Agregar(9);
FinAlgoritmo
